// DAILY RELEASE OVERRIDES — GENERATED by curio-hq tools/export_daily_overrides.js.
// Do not hand-edit. Empty DAYS = the daily walk behaves exactly as before.
//
// Release control (curio-hq 03-Engine/question-intelligence/release-control/):
// when the CEO rejects a question or a set for a specific date, the approved
// replacement five is recorded here BY BANK POSITION. Replacements are drawn
// only from that day's own 8-card window, so the walk's within-epoch
// no-repeat guarantee is untouched. resolve() returns null on ANY mismatch
// (kids pool, re-cut deck after a bank change, stale index) and the app
// falls back to the pacer — overrides can never break the daily.
(function () {
  "use strict";

  var DAYS = {};

  // resolve(dateKey, win, indexOf, count) -> [five cards] | null
  //   dateKey — "YYYY-MM-DD" derived from the walk's day number
  //   win     — the day's dealt window (question objects)
  //   indexOf — maps a window card to its 1-based bank position
  //   count   — DAILY_COUNT; the override must name exactly this many cards
  function resolve(dateKey, win, indexOf, count) {
    var five = DAYS[dateKey];
    if (!five || five.length !== count) return null;
    var slots = {}, i;
    for (i = 0; i < win.length; i++) slots[indexOf(win[i])] = win[i];
    var out = [];
    for (i = 0; i < five.length; i++) {
      var c = slots[five[i]];
      if (!c) return null; // not in this day's window — refuse, fall back
      out.push(c);
    }
    return out;
  }

  window.CURIO_DAILY_OVERRIDES = { days: DAYS, resolve: resolve };
})();
